target = '......((.((..((..(...(.((.((....))))..)...(.((..((....))..))..)...).))..)))).....................'
print(f'Length: {len(target)}')
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

# Print pairs sorted
for i in sorted(pairs.keys()):
    if i < pairs[i]:
        print(f'({i:2d}, {pairs[i]:2d})')

print(f'Total pairs: {len([k for k in pairs if k < pairs[k]])}')

# Show structure
for i in range(len(target)):
    if i in pairs and i < pairs[i]:
        print(f'  pos {i}: ({target[i]}) pairs with {pairs[i]}')
    elif i in pairs:
        print(f'  pos {i}: ({target[i]}) pairs with {pairs[i]}')
    else:
        print(f'  pos {i}: ({target[i]}) unpaired')
"

